{
    /// <summary>客户端注册频道时替换为固定列表，避免真实客户端频道与服务端不一致。</summary>
    internal static byte[] ChannelList { get; } = Convert.FromHexString("464d4c7c485300464d4c00464d4c7c4d5000464d4c00616e74696d6f6400647261676f6e636f72653a6d61696e006e65746f7074696d697a6500464f52474500786165726f6d696e696d61703a6d61696e006d6f62656e64730061726d6f7572657273");

    /// <summary>FML|HS 模组列表载荷（判别字节 0x02 + 模组数量 + 名称/版本）。</summary>
    internal static byte[] FmlModListData { get; } = Convert.FromHexString("");

    internal static bool IsEnabled(MinecraftConnection connection) => ServerGameIds.IsGame(connection, ServerGameIds.Czsczl);
}
